public int minPlatforms(int[] arr, int[] dep) {
    int n = arr.length;
    int peak = 0;
    for (int i = 0; i < n; i++) {
        int present = 0;
        for (int j = 0; j < n; j++) {
            // Train j is present at the instant train i arrives.
            if (arr[j] <= arr[i] && arr[i] <= dep[j]) {
                present++;
            }
        }
        peak = Math.max(peak, present);
    }
    return peak;
}

