def min_platforms(self, arr: list[int], dep: list[int]) -> int:
    n = len(arr)
    peak = 0
    for i in range(n):
        present = 0
        for j in range(n):
            if arr[j] <= arr[i] <= dep[j]:
                present += 1
        peak = max(peak, present)
    return peak

code.java:
public int minPlatforms(int[] arr, int[] dep) {
    int n = arr.length;
    Arrays.sort(arr);
    Arrays.sort(dep);
    int i = 0, j = 0;
    int platforms = 0, peak = 0;
    while (i < n) {
        if (arr[i] <= dep[j]) {
            platforms++;            // a train arrives
            peak = Math.max(peak, platforms);
            i++;
        } else {
            platforms--;            // the earliest occupied train leaves
            j++;
        }
    }
    return peak;
}

